def double(x):
    return x * 2
result = double(7) + 1

def area(width, height):
    return width * height
result = area(3, 4) - 2

def greet(name, punctuation="!"):
    return "Hi " + name + punctuation
result = greet("Ana", punctuation="?")

def leaf_count(level):
    if level == 0:
        return 1
    return 2 * leaf_count(level - 1)
result = leaf_count(4)

def f(n):
    if n == 0: return 1
    return n * f(n - 1)

def count_items(items):
    if not items:
        return 0
    return 1 + count_items(items[1:])
result = count_items([5, 6, 7, 8])

def total_to(n):
    if n == 0:
        return 0
    return n + total_to(n - 1)
result = total_to(4)

