def reverse(text):
    if len(text) <= 1:
        return text
    return reverse(text[1:]) + text[0]
result = reverse("abc")

def shipping(weight):
    if weight <= 2:
        return 5
    return 5 + (weight - 2) * 3
result = shipping(4) + shipping(1)

def stack_notes(n):
    if n == 0:
        return 'end'
    return stack_notes(n - 1) + str(n)
result = stack_notes(3)

def label_depth(n):
    if n < 4:
        return 'small'
    return label_depth(n // 2) + '!'
result = label_depth(20)

def digits(n):
    if n < 10:
        return 1
    return 1 + digits(n // 10)
result = digits(5432)

def notify():
    print('ready')
status = notify()

def down(n):
    if n == 0:
        return 0
    return down(n - 1)
down(2)

def repeat_mark(n):
    if n == 0:
        return ''
    return '*' + repeat_mark(n - 1)
result = repeat_mark(3)

def pulse(n):
    if n <= 0:
        return 'done'
    return pulse(n - 1)

def steps(n):
    if n == 0:
        return 0
    return 1 + steps(n - 2)

def count_to(n):
    if n == 0:
        return 0
    return 1 + count_to(n - 1)
